function clsx(...args) {
  return args.filter(Boolean).join(" ");
}

function Progress({ value }) {
  return (
    <div className="bar">
      <div className="fill" style={{ width: value + "%" }} />
    </div>
  );
}

function App() {
  const [active, setActive] = useState(false);
  const [value, setValue] = useState(30);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button className={clsx("btn", active && "btn-active")} onClick={() => setActive(!active)}>
        {active ? "Active" : "Inactive"}
      </button>
      <Progress value={value} />
      <input type="range" min="0" max="100" value={value} onChange={(e) => setValue(Number(e.target.value))} />
    </div>
  );
}

topics.description:
**CSS-in-JS** colocates styles with components. **styled-components** and **Emotion** let you create components that carry their own CSS.

```jsx
import styled from "styled-components";

const Button = styled.button`
  padding: 8px 16px;
  border-radius: 6px;
  background: ${(p) => (p.$primary ? "#0ea5e9" : "white")};
  color: ${(p) => (p.$primary ? "white" : "#0ea5e9")};

  &:hover { opacity: 0.85; }
  @media (max-width: 600px) { width: 100%; }
`;

<Button $primary>Save</Button>
```

### Features

- **Props-based styling** - use `$transient` props (prefixed `$`) so they are not forwarded to the DOM.
- **Real CSS**: nesting, pseudo-classes, media queries, keyframes (`keyframes`), global styles (`createGlobalStyle`).
- **Extending**: `styled(Button)` creates a variant.
- **Theming**: `ThemeProvider` provides a theme object read as `props.theme`.
- **Auto-generated unique class names** - no collisions, dead-code elimination by design.
- `css` helper for reusable snippets and `as` prop to change the rendered tag.

### Trade-offs (see the tradeoffs topic)

Runtime style injection costs performance and doesn't fit React Server Components well. styled-components is in **maintenance mode**, and many teams moved to zero-runtime options (CSS Modules, Tailwind, vanilla-extract, Panda CSS, StyleX, Linaria).

### When to use

Existing projects already using it, design-system libraries with heavy prop-driven variants, and teams who like colocated styles.

examples.code:
import styled, { ThemeProvider, keyframes, createGlobalStyle } from "styled-components";

const GlobalStyle = createGlobalStyle`
  body { margin: 0; font-family: system-ui, sans-serif; }
`;

const spin = keyframes`from { transform: rotate(0) } to { transform: rotate(360deg) }`;

const Card = styled.div`
  background: ${({ theme }) => theme.card};
  color: ${({ theme }) => theme.text};
  padding: 16px;
  border-radius: 12px;
`;

const Button = styled.button`
  padding: 8px 14px;
  border: 0;
  border-radius: 6px;
  background: ${({ $variant, theme }) => ($variant === "danger" ? theme.danger : theme.primary)};
  color: #fff;
  &:hover { filter: brightness(1.1); }
`;
const DangerButton = styled(Button)`font-weight: bold;`;

const Loader = styled.span`
  display: inline-block;
  animation: ${spin} 1s linear infinite;
`;

const theme = { card: "#fff", text: "#111", primary: "#0ea5e9", danger: "#ef4444" };

export default function App() {
  return (
    <ThemeProvider theme={theme}>
      <GlobalStyle />
      <Card>
        <Button $variant="primary">Save</Button> <DangerButton $variant="danger">Delete</DangerButton>
        <Loader>*</Loader>
      </Card>
    </ThemeProvider>
  );
}

import clsx from "clsx";
import { twMerge } from "tailwind-merge";

const cn = (...a) => twMerge(clsx(a));

const variants = {
  primary: "bg-sky-500 text-white hover:bg-sky-600",
  outline: "border border-sky-500 text-sky-600 hover:bg-sky-50",
  danger: "bg-red-500 text-white hover:bg-red-600",
};
const sizes = { sm: "px-3 py-1 text-sm", md: "px-4 py-2", lg: "px-6 py-3 text-lg" };

export function Button({ variant = "primary", size = "md", className, ...props }) {
  return (
    <button
      className={cn(
        "rounded-lg font-semibold transition focus:outline-none focus:ring-2 disabled:opacity-50",
        variants[variant],
        sizes[size],
        className
      )}
      {...props}
    />
  );
}

